T[67] = { note = "Сначала ее там нет. В канализации, после Атрексиса, зачисти северо-восточную комнату, с рыночными прилавками и маленьким розовым кругом призыва (не большой круг Атрексиса). Игрок с Томом Даларана при себе нажимает на круг, и Лин выходит из большой круглой решетчатой двери. Чтобы получить том, возьми Черный том на столе в комнате верховного мага Аругала в Крепости Темного Клыка, после убийства Аругала, затем используй его у Leyline Focus, синего кристалла в задней комнате Янтарной мельницы в Серебристом бору.", { "Залп стрел Тьмы", "Стрелы Тьмы по всем в радиусе 30 метров от нее." }, { "Проклятие шипов", "Заклинание 1,5 секунды: проклятие на 3 минуты, которое время от времени ранит игрока, когда он атакует. Сними его." }, { "Скелеты", "Скелеты поднимаются и сражаются рядом с ней. Убей их." } }
T[68] = { note = "Верховный маг Модера открывает группе портал в пурпурную комнату: он ведет к нему.", { "Скачущая мана", "Шар летит к случайному игроку, а затем возвращается к нему. Все, через кого он проходит, получают урон от тайной магии и немеют на 6 секунд: не вставай между ним и этим игроком." }, { "Массовое превращение", "Когда у него кончается мана, он превращает всю группу в животных на 8 секунд, затем 6 секунд направляет Прикосновение, чтобы восстановить ее." }, { "Замедление", "Замедляет всех вокруг него на 3 секунды: атаки и заклинания медленнее на 30%, передвижение медленнее на 70%." }, { "Оставайтесь в комнате", "Если кто-то выйдет из комнаты во время боя, он вернется с полным здоровьем." } }
T[69] = { { "Сеть", "Обездвиживает всех рядом с ним на 10 секунд." }, { "Замедление", "Замедляет атаки и передвижение игрока на 10 секунд и может оглушить его." }, { "Призыв механического таракана", "Призывает механических тараканов. Его обновление убивает их и лечит его." } }
T[70] = { note = "Поговори с мастером-подрывником Emi Shortfuse и защищай ее, пока она взрывает два входа в пещеры. Троггы приходят волнами, затем появляется Грюббис с Chomper." }
T[71] = { { "Мегавольт", "Урон от сил природы в конусе перед ним (заклинание 2 секунды). Перед ним стоит только танк." }, { "Цепная молния", "Молния, прыгающая по ближним игрокам (заклинание 2,5 секунды). Прерви его." } }
T[72] = { { "Косить толпу", "Бьет всех рядом с ним и прерывает их заклинания. Заклинатели и лекари, держитесь на расстоянии." }, { "Дугообразный удар", "Бьет всех в конусе перед ним." }, { "Топтание", "Бьет всех, кто стоит рядом с ним." } }
T[73] = { { "Призыв пылающего слуги", "Призывает двух пылающих слуг в начале боя." }, { "Огненный шар", "Он держится на расстоянии, чтобы колдовать. Прерви его." }, { "Огненный щит II", "Урон от огня всем, кто рядом с ним, в течение минуты. Жрец или шаман может его снять." } }
T[74] = { { "Ходячие бомбы", "Он по очереди включает головы гномов вокруг зала, и каждая выпускает ходячие бомбы, которые взрываются, добежав до игрока. Кнопка рядом с головой ее выключает. Ниже половины здоровья он включает их быстрее." }, { "Отбрасывание", "Отбрасывает танка. Ниже половины здоровья это задевает всех вокруг него." } }
T[75] = { { "Призыв духа вепря", "Призывает Дух вепря к себе каждые 30-45 секунд (заклинание 1,5 секунды). Убивай каждого, прежде чем придет следующий." }, { "Цепное исцеление", "Когда здоровья меньше 75%, он лечит себя, и лечение перескакивает на двух союзников рядом (заклинание 2,5 секунды). Прерви его." } }
T[76] = { { "Господство над разумом", "Берет под контроль игрока, не являющегося его целью, на 15 секунд (заклинание 2 секунды). Прерви его или рассей эффект на игроке." }, { "Стрела Тьмы", "Он держится на расстоянии, чтобы колдовать. Прерви его." } }
T[77] = { { "Зовет на помощь", "Когда ты нападаешь на него, он зовет существ в радиусе 15 метров, в том числе двух метателей из Иглошкурых рядом с ним. Держи одного из двух под контролем во время боя." }, { "Раскат грома", "Каждые 8-14 секунд: урон от сил природы всем рядом с ним, а их атаки и передвижение замедляются на 10 секунд." } }
T[78] = { { "Крутящийся заряд", "Бьет всех, кто стоит рядом с ним." }, { "Аура возмездия", "Любой, кто ударит его или союзника рядом (в том числе Властителя Таранного Клыка), получает урон от сил природы." } }
T[79] = { note = "Защитное поле закрывает его пещеру. Убей двух стражей Мертвой Головы, стоящих перед ней: оно падает, когда оба мертвы.", { "Притворная смерть", "Каждые 21-35 секунд он бьет игрока, не являющегося его целью, который падает как мертвый и больше не может атаковать или колдовать. Движение прекращает эффект." }, { "Буйство", "Каждые 25-31 секунду: бьет всех рядом с собой и оглушает их на 2,5 секунды." }, { "Исступление", "При 60% здоровья, затем при 40%, он атакует на 60% быстрее и бьет сильнее в течение 2 минут." } }
T[80] = { note = "Редкая летучая мышь: она бывает не при каждом проходе. Когда она есть, она ждет в небольшой нише стены пещеры летучих мышей, рядом с Чарлгой Остробок." }
T[81] = { { "Цепной удар", "Она держится на расстоянии и колдует его снова и снова: молния, которая перескакивает максимум на 3 игроков (заклинание 2,5 секунды). Прерви ее." }, { "Чистота", "Каждые 9-15 секунд она неуязвима для всех атак и заклинаний на 2 секунды." }, { "Обновление", "Лечит раненого союзника или себя в течение 15 секунд. Жрец или шаман может его снять." } }
T[82] = { { "Призыв грохотуна", "Каменный грохотун сопровождает его и сражается рядом с ним." }, { "Молния", "Он держится на расстоянии, чтобы колдовать. Прерви его." }, { "Бежит за помощью", "При 15% здоровья он убегает за помощью. Добей его, пока он не убежал далеко." } }
T[83] = { { "Призыв грохотуна", "Каменный грохотун сопровождает его и сражается рядом с ним." }, { "Молния", "Он держится на расстоянии, чтобы колдовать. Прерви его." } }
T[84] = { { "Слово Тьмы: Боль", "Урон от темной магии по его цели каждые 3 секунды в течение 18 секунд. Рассеивание заклинаний снимает его." } }
T[85] = { note = "Примерно в одной партии из трех один из трех редких монстров кладбища стоит в одном из шести мест на карте: Azshir the Sleepless, Fallen Champion или Ironspine.", { "Зов могилы", "Через 60 секунд урон от темной магии по игроку (заклинание 2 секунды). Маг или друид может снять его раньше." }, { "Запугивание", "Заставляет игрока бежать в страхе 4 секунды." }, { "Вытягивание души", "При здоровье ниже половины он вытягивает здоровье у игрока и ближайшего к нему игрока в течение 12 секунд и лечит себя." } }
T[86] = { note = "Примерно в одной партии из трех один из трех редких монстров кладбища стоит в одном из шести мест на карте: Azshir the Sleepless, Fallen Champion или Ironspine.", { "Рассекающий удар", "Бьет свою цель и ближайшего к ней игрока." }, { "Казнь", "Сильно бьет цель с 20% здоровья или меньше. Держи танка выше этого порога." } }
T[87] = { note = "Примерно в одной партии из трех один из трех редких монстров кладбища стоит в одном из шести мест на карте: Azshir the Sleepless, Fallen Champion или Ironspine.", { "Проклятие слабости", "Снижает физический урон всех в радиусе 30 метров на 2 минуты. Маг или друид может его снять." }, { "Ядовитое облако", "Урон от сил природы каждые 5 секунд в течение 45 секунд всем, кто рядом." } }
T[88] = { { "Пламенный шип", "Столб пламени там, где стоит игрок (заклинание 3 секунды): урон от огня, затем еще каждые 3 секунды в течение 9 секунд. Выйди из него." }, { "Кольцо огня", "Урон от огня всем в радиусе 10 метров от него." }, { "Огненный шок", "Урон от огня по игроку, затем еще каждые 3 секунды в течение 12 секунд. Рассеивание заклинаний снимает его." }, { "Стрела Тьмы", "Он держится на расстоянии, чтобы колдовать. Прерви его." } }
T[89] = { { "Алые гончие", "Три пса сопровождают его и атакуют вместе с ним, а он еще накладывает на них Кровожадность. Убей их первыми." }, { "Кровожадность", "Ускоряет его атаки или атаки союзника на 30% на 30 секунд. Жрец или шаман может ее снять." }, { "Боевой крик", "Больше силы атаки для него и его псов на 3 минуты." } }
T[90] = { { "Мгновенный взрыв", "При половине здоровья он запирается на 8 секунд в Чародейском пузыре и применяет Мгновенный взрыв (заклинание 5 секунд): тяжелый урон от огня всем в радиусе 30 метров. Выйди из зоны до взрыва, затем вернись." }, { "Превращение", "Превращает в овцу игрока, не являющегося его целью, до 20 секунд (заклинание 1,5 секунды). Прерви его или рассей эффект на игроке." }, { "Молчание", "Накладывает безмолвие на всех в радиусе 15 метров на 10 секунд (заклинание 1,5 секунды). Если ты лечишь, держись дальше." }, { "Чародейский взрыв", "Каждые несколько секунд урон от тайной магии всем в радиусе 10 метров. Дальнобойные, держитесь на расстоянии." } }
T[91] = { { "Вихрь", "Каждые 15-25 секунд он крутится 10 секунд и бьет всех рядом с собой. В ближнем бою отойди до конца." }, { "Рассекающий удар", "Бьет свою цель и ближайшего к ней игрока." }, { "Исступление", "При 30% здоровья он атакует на 60% быстрее и бьет сильнее в течение 2 минут." }, { "Молодые алые рекруты", "После его смерти 20 молодых алых рекрутов входят через дверь комнаты и нападают. Оставайся с группой и используй урон по площади." } }
T[92] = { { "Проклятие Тутен'каш", "Проклятие, снижающее скорость сотворения заклинаний на 15% и замедляющее атаки на 18% у ближайших игроков на 15 мин. Снимите проклятие." } }
