T[97] = { { "Иссушающее прикосновение", "Болезнь, наносящая урон тенью и похищающая ману каждые 10 сек в течение 3 мин; мана переходит к нему. Излечите её, особенно у заклинателей." }, { "Гнилостная вонь", "Снижает Силу и Ловкость ближайших игроков на 50 на 10 сек и не даёт им колдовать. Заклинатели, держитесь подальше от него." } }
T[98] = { note = "Он лежит на полу в маленькой комнате рядом с алтарем, как мертвый, и встает, когда его атакуют.", { "Страх", "Заставляет игрока в ужасе бежать до 8 секунд (заклинание 1,5 секунды). Прерви его." }, { "Сон", "Усыпляет всех рядом с ним до 10 секунд. Урон будит спящего." }, { "Проклятие крови", "Игрок получает больше физического урона в течение 10 минут (заклинание 2 секунды). Маг или друид может его снять." }, { "Исцеление", "При 30% здоровья он лечит себя (заклинание 3 секунды). Прерви его." } }
T[99] = { { "Зовет на помощь", "Когда ты нападаешь на него, он зовет всех алых защитников в радиусе 80 метров. Зачисть собор, прежде чем нападать на него." }, { "Молот правосудия", "Оглушает игрока на 5 секунд." }, { "Божественный щит", "При половине здоровья он становится неуязвим для любого урона и всех заклинаний на 12 секунд." }, { "Аура воздаяния", "Урон от светлой магии любому, кто бьет его в ближнем бою." } }
